import { ALL_ITEMS, type NavItem } from "@/lib/nav";

export type LearningLesson = {
  title: string;
  concept: string;
  equation: string;
  fieldExample: string;
  takeaway: string;
  question: string;
  options: string[];
  answer: number;
  explanation: string;
};

export type LearningCourse = NavItem & {
  id: string;
  group: string;
  level: "Foundation" | "Applied" | "Advanced";
  minutes: number;
  outcomes: string[];
  lessons: LearningLesson[];
  sources: string[];
};

type CourseContent = {
  level: "Foundation" | "Applied" | "Advanced";
  minutes: number;
  outcomes: string[];
  lessons: LearningLesson[];
};

function lesson(
  title: string,
  concept: string,
  equation: string,
  fieldExample: string,
  takeaway: string,
  question: string,
  options: string[],
  answer: number,
  explanation: string,
): LearningLesson {
  const correctOption = options[answer];
  const offset = title.split("").reduce((total, character) => total + character.charCodeAt(0), 0) % options.length;
  const shuffledOptions = options.map((_, index) => options[(index + offset) % options.length]);
  return {
    title,
    concept,
    equation,
    fieldExample,
    takeaway,
    question,
    options: shuffledOptions,
    answer: shuffledOptions.indexOf(correctOption),
    explanation,
  };
}

